      formula("r2-coupon-formula", "Price an annual fixed-coupon bond", String.raw`C=cF,\qquad P=C\frac{1-(1+y)^{-n}}{y}+\frac{F}{(1+y)^n}`, [["C", "Annual coupon payment", "currency per year"], ["c", "Annual coupon rate", "decimal per year"], ["F", "Face value repaid at maturity", "currency"], ["P", "Bond value immediately after a coupon date", "currency"], ["y", "Effective annual yield to maturity", "decimal per year"], ["n", "Remaining annual payments", "years"]], ["Annual coupons, fixed positive promised payments, no default, and valuation on a coupon date immediately after payment."], "1+y>0; y is nonzero in this closed form; at y=0, P=nC+F.", "The coupon annuity and discounted principal are separate components; price and yield move in opposite directions."),
      formula("r2-annuity", "Finite annuity and fully amortizing payment", String.raw`PV=A\frac{1-(1+r)^{-n}}{r},\qquad A=\frac{rPV}{1-(1+r)^{-n}},\qquad PV_{\rm due}=(1+r)PV_{\rm ordinary}`, [["A", "Equal periodic payment", "currency per payment"], ["PV", "Present value or original loan principal", "currency"], ["r", "Effective rate per payment period", "decimal per period"], ["n", "Number of payments", "periods"], ["PV_{\\rm due},PV_{\\rm ordinary}", "Values of beginning- and end-of-period payment streams", "currency"]], ["The first two expressions assume period-end payments and no residual terminal loan balance.", "The annuity due shifts the identical payment stream one period earlier."], "n is a positive integer; 1+r>0 and r is nonzero in the displayed fractions; if r=0, PV=nA and A=PV/n.", "A level loan payment must recover the current principal as well as compensate for waiting."),
      formula("r2-amortization", "Separate interest from repayment", String.raw`I_t=rB_{t-1},\qquad Q_t=A-I_t,\qquad B_t=B_{t-1}-Q_t`, [["I_t", "Interest paid in period t", "currency"], ["Q_t", "Principal repaid in period t", "currency"], ["B_{t-1},B_t", "Opening and closing loan balances", "currency"], ["A", "Level period-end payment", "currency"], ["r", "Fixed interest rate per payment period", "decimal per period"]], ["Payments are made on time, no fees or additional borrowing are included, and the loan is fully amortizing."], "The scheduled payment covers accrued interest; use unrounded intermediate balances and reconcile final rounding.", "Interest is charged on what remains outstanding, so each payment gradually shifts toward principal."),
      formula("r2-perpetuity", "Perpetual bond or fixed dividend", String.raw`V_0=\frac{A}{r},\qquad V_{\rm preferred}=\frac{D_p}{k_p}`, [["V_0,V_{\\rm preferred}", "Present values of the perpetual payment stream and preferred share", "currency"], ["A", "Constant payment beginning next period", "currency per period"], ["D_p", "Preferred dividend beginning next period", "currency per share per period"], ["r,k_p", "Required returns for the respective payment streams", "decimal per period"]], ["Payments continue forever without growth; no final redemption payment or changing dividend terms are included."], "r>0 and k_p>0 for finite values of positive payment streams.", "A stated coupon or preferred dividend rate first determines A or Dp; it is not automatically the discount rate."),
      formula("r2-gordon", "Constant-growth dividend value", String.raw`D_1=D_0(1+g),\qquad V_0=\frac{D_1}{k_e-g}`, [["D_0,D_1", "Most recent and next expected dividend", "currency per share"], ["V_0", "Current share value", "currency per share"], ["k_e", "Required equity return", "decimal per period"], ["g", "Perpetual dividend growth rate", "decimal per period"]], ["Dividends grow at the same rate forever, the discount rate is constant, and the first future payment occurs one period from now."], "k_e>g; 1+k_e>0; 1+g>0; dividends and rates use matching periods.", "The numerator is next period's dividend; the denominator captures the offsetting effects of required return and growth."),
      formula("r2-multistage", "Explicit dividends plus terminal value", String.raw`V_H=\frac{D_{H+1}}{k_e-g_L},\qquad V_0=\sum_{t=1}^{H}\frac{D_t}{(1+k_e)^t}+\frac{V_H}{(1+k_e)^H}`, [["H", "Final explicit forecast period", "periods"], ["D_t", "Dividend forecast for explicit period t", "currency per share"], ["D_{H+1}", "First dividend in the perpetual stable-growth phase", "currency per share"], ["V_H,V_0", "Values at the end of H and today", "currency per share"], ["k_e,g_L", "Required return and perpetual long-run growth", "decimal per period"]], ["After period H, dividends grow at gL forever; one constant required return is suitable for all modeled dividends."], "H is a positive integer; k_e>g_L; 1+k_e>0; the dividend at H is not included in V_H.", "Terminal value belongs one period before its numerator's dividend and must be discounted from that date."),
      formula("r2-implied", "Infer a compound yield", String.raw`r=\left(\frac{FV}{P}\right)^{1/n}-1,\qquad P=\sum_{t=1}^{n}\frac{CF_t}{(1+y)^t}`, [["FV", "Single terminal payment in the first expression", "currency"], ["P", "Observed current price", "currency"], ["n", "Number of periods", "periods"], ["r", "Single-payment implied return", "decimal per period"], ["CF_t", "Scheduled payment in period t", "currency"], ["y", "Numerically solved stream yield", "decimal per period"]], ["The root formula applies to one terminal payment; coupon bonds require solving the full stream equation."], "P>0; FV>0; n>0; 1+y>0; positive scheduled cash flows imply an inverse price-yield relationship.", "The implied rate reproduces today's price under the specified payments and compounding convention."),
      formula("r2-equity-implied", "Infer equity return or growth", String.raw`k_e=\frac{D_1}{P_0}+g,\qquad g=k_e-\frac{D_1}{P_0},\qquad k_p=\frac{D_p}{P_0}`, [["P_0", "Observed share price", "currency per share"], ["D_1", "Next expected common dividend", "currency per share"], ["g,k_e", "Constant dividend growth and required common return", "decimal per period"], ["D_p,k_p", "Constant preferred dividend and implied preferred return", "currency per share and decimal per period, respectively"]], ["Common dividends follow perpetual constant growth; preferred dividends remain constant in perpetuity."], "P0>0; common model requires k_e>g and matching dividend/rate periods; preferred dividends are positive.", "Price plus one assumed growth or return input determines the other; price alone does not identify both."),
      formula("r2-retention", "Link retention to sustainable growth", String.raw`b=1-\frac{D}{E},\qquad g=b\,ROE`, [["b", "Earnings retention ratio", "fraction"], ["D,E", "Dividends and earnings measured on the same total or per-share basis", "currency"], ["ROE", "Expected return on common equity", "decimal per period"], ["g", "Sustainable earnings and dividend growth under stable payout", "decimal per period"]], ["Retention, return on equity, and financing policy remain stable; retained earnings support growth without dilutive new equity.", "Stable payout connects earnings growth to dividend growth; definitions of ROE and the growth interval must be consistent."], "E>0 for the payout interpretation; ordinarily 0<=b<=1; perpetual valuation separately requires required return>g.", "Retaining a larger earnings share supports more growth only if the business can earn the assumed return on those funds."),
      formula("r2-additivity", "Add and scale matched cash-flow claims", String.raw`PV(aX+bY)=aPV(X)+bPV(Y)`, [["X,Y", "Cash-flow streams specified by date and state", "currency at each date and state"], ["a,b", "Holdings in each stream; negative holdings are short positions", "units of each claim"], ["PV", "Value at the common valuation date", "currency"]], ["Consistent valuation factors and linear tradable claims; applying the equality as a no-arbitrage trade requires accessible trading and financing."], "Match currency, dates, and state-contingent payments; equal expected cash flow alone is insufficient.", "A stream can be split into convenient pieces or replicated by combining other securities without changing its value."),
      formula("r2-forward", "Derive a forward rate for any matched interval", String.raw`(1+z_n)^n=(1+z_m)^m(1+f_{m,n-m})^{n-m},\qquad f_{m,n-m}=\left[\frac{(1+z_n)^n}{(1+z_m)^m}\right]^{1/(n-m)}-1`, [["z_m,z_n", "Annual-compounded spot yields for maturities m and n", "decimal per year"], ["m,n", "Spot maturities measured from today", "years"], ["f_{m,n-m}", "Annualized forward rate starting at m and lasting n-m years", "decimal per year"]], ["Equal credit quality, matched horizons, annual compounding, and frictionless borrowing/lending; the forward is contracted today."], "n>m>0; all gross interest factors are positive.", "Investing to n directly must match investing to m and then using the contracted forward rate until n."),
      formula("r2-fx-replication", "Forward exchange rate with explicit currency units", String.raw`F_{p/b}=S_{p/b}\frac{1+r_p}{1+r_b},\qquad \frac{F_{p/b}}{S_{p/b}}-1=\frac{r_p-r_b}{1+r_b}\approx r_p-r_b`, [["S_{p/b},F_{p/b}", "Spot and forward exchange quotes", "price currency per unit of base currency"], ["r_p,r_b", "Price- and base-currency interest rates for the contract term", "decimal over the contract term"]], ["Same settlement date and comparable risk; no transaction costs or funding restrictions; rates are effective for the complete contract period."], "1+rp>0 and 1+rb>0; the approximation is useful only when rb is small.", "The price currency's gross rate goes in the numerator; the forward premium offsets the covered investment's interest-rate difference."),
      formula("r2-option-payoff", "Call and put payoffs at expiration", String.raw`C_T=\max(S_T-K,0),\qquad P_T=\max(K-S_T,0),\qquad S_u=S_0u,\quad S_d=S_0d`, [["C_T,P_T", "Terminal call and put payoffs", "currency per underlying share"], ["S_T,S_0,S_u,S_d", "Underlying price at expiration, today, up state, and down state", "currency per share"], ["K", "Option exercise price", "currency per share"], ["u,d", "Up-state and down-state gross asset-return factors", "unitless"]], ["Each option covers one share and is evaluated at its expiration; exercise is optional."], "Su>Sd; u and d are positive; payoff excludes the initial premium and financing costs.", "A holder exercises only when doing so has positive value; writing an option reverses the holder's payoff."),
      formula("r2-replication", "One-period call hedge and replication", String.raw`h=\frac{C_u-C_d}{S_u-S_d},\quad H=hS_u-C_u=hS_d-C_d,\quad B_0=\frac{H}{1+r_f},\quad C_0=hS_0-B_0`, [["C_u,C_d,C_0", "Up-state payoff, down-state payoff, and current call value", "currency per underlying share"], ["S_0,S_u,S_d", "Current underlying price and its two terminal prices", "currency per share"], ["h", "Hedge ratio: underlying shares per call", "shares per option"], ["H", "Certain terminal value of shares minus one call", "currency"], ["B_0", "Present value of H, borrowed for the call replica", "currency"], ["r_f", "Risk-free return for the option's complete remaining period", "decimal per period"]], ["One expiration date and two asset-price outcomes, no dividends, frictionless short selling and financing, and the same borrowing and lending rate."], "Su>Sd and 1+rf>0; Sd<S0(1+rf)<Su rules out stock/financing arbitrage in the nondegenerate case.", "Shares minus a written call form a certain payment; shares financed by borrowing the value of that payment reproduce the call.")
